int unicoder_utf32_decode(uint32_t *coder_length, unsigned char *utf32, int utf32_size) { if (utf32_size != 2 && utf32_size != 1) return -4; if (!utf32) return -1; if (!coder_length) return -1; unsigned int i, result = 0; for (i = 0; i < 4; i++) { if (utf32_size == 2) { if (i > 0) result <<= 8; result |= (uint32_t) utf32[i]; } else { if (i > 0) result >>= 8; result |= (uint32_t) utf32[i] << 24; } } if (result >0x10FFFF) return -16; if (result >=0xD800 && result <0xE000) return -16; *coder_length = result; return 4; }